command:
// ==========================================
// LUNAS WIRKUNG: SEELENBINDUNG (ZERZAL)
//
// - 1 gültiges Lebewesen im Target, das den Effekt/Status "Besiegt" besitzt
// - alle weiteren / ungültigen Targets = Misserfolg, Gabe geht dennoch durch
// - nutzt DSK.Wesen.IstLebendig + Prüfung auf "Besiegt"
// - direktes neues Kartenlayout über DSK.GabenUI.AnfrageKarteErstellen
// ==========================================

(async function () {
    // +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++++++
    const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
    const frameworkFehlt =
        !globalThis.DSK?.QS?.Ermitteln || !globalThis.DSK?.Token?.Finde ||
        !globalThis.DSK?.Wesen?.IstLebendig ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen;

    if (frameworkFehlt) {
        const fwMacro = await fromUuid(frameworkUuid);
        if (!fwMacro?.execute) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
        await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150));
    }

    const DSK_FW = globalThis.DSK;
    if (
        !DSK_FW?.QS?.Ermitteln || !DSK_FW?.Token?.Finde ||
        !DSK_FW?.Wesen?.IstLebendig ||
        !DSK_FW?.GabenUI?.AnfrageKarteErstellen
    ) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework 01.02 wurde nicht vollständig geladen!");

    // +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++++++
    const gabenName = "Seelenbindung", vollerName = "Seelenbindung (Zerzal)", ahne = "Zerzal";
    const dauerText = "Permanent (bis zur Zerstörung)";

    // +++ 3 - HELFER ++++++++++++++++++++++++++++++++++++++++++++++
    const raeumeQSAuf = async actor => {
        if (actor?.getFlag("world", "letzteGabenQS") !== undefined) await actor.unsetFlag("world", "letzteGabenQS");
        if (actor?.getFlag("world", "letzteGabenMessageId") !== undefined) await actor.unsetFlag("world", "letzteGabenMessageId");
    };

    const istSterblichesLebewesen = actor => {
        if (!actor) return false;
        return DSK_FW.Wesen.IstLebendig(actor, {
            zusaetzlichAusgeschlossen: ["elementar", "pflanze"]
        });
    };

    // Prüft auf den aktiven Effekt / Status "Besiegt"
    const istBesiegt = (actor, token = null) => {
        if (!actor) return false;

        if (token?.combatant?.defeated === true) return true;

        return (actor.effects || []).some(effekt => {
            if (effekt.disabled) return false;

            const name = String(effekt.name || effekt.label || "").trim().toLowerCase();
            if (name === "besiegt" || name.includes("besiegt")) return true;

            const statusIds = Array.from(effekt.statuses || []).map(s => String(s).toLowerCase());
            if (statusIds.some(s => ["dead", "defeated", "besiegt"].includes(s))) return true;

            const coreStatus = String(effekt.getFlag("core", "statusId") || "").toLowerCase();
            return ["dead", "defeated", "besiegt"].includes(coreStatus);
        });
    };

    const beschreibungFuer = (casterName, targetName) =>
        `<b>${casterName}</b> setzt die Seele von <b>${targetName}</b> in dessen Schädel gefangen.` +
        `<br><br>Die Seele bleibt von nun an in diesem Schädel gebunden und ist dem Willen des Zerzalkindes unterworfen. ` +
        `Manche Seelen gewöhnen sich an die Gefangenschaft und werden Freunde, andere hegen tief in ihrem Inneren einen wachsenden Groll und warten nur auf Rache.` +
        `<br><br><b>Voraussetzungen:</b>` +
        `<br>• Die Beute muss den Status <b>Besiegt</b> besitzen und vom Zerzalkind <b>alleine</b> getötet worden sein.` +
        `<br>• Der Tod darf nicht länger als <b>1 Stunde</b> zurückliegen.` +
        `<br><br><i>Um die Seele zeitweise aus ihrem Gefängnis zu befreien, benötigt das Zerzalkind die Gabe „Geisterdiener“. Wird der Schädel zerstört, entweicht die Seele ins Jenseits und ist frei.</i>` +
        `<br><br><b>Zielkategorie:</b> Besiegtes Lebewesen`;

    // +++ 4 - WIRKENDER +++++++++++++++++++++++++++++++++++++++++++
    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;

    if (!casterActor) {
        casterActor =
            canvas.tokens.placeables.map(token => token.actor).find(actor =>
                actor?.getFlag("world", "letzteGabenQS") !== undefined
            ) ||
            game.actors.find(actor =>
                actor.getFlag("world", "letzteGabenQS") !== undefined
            ) ||
            null;
    }

    if (!casterActor) {
        return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");
    }

    if (!game.user.isGM && !casterActor.isOwner) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!"
        );
    }

    const casterName = DSK_FW.ResolveTokenName(casterActor);

    // +++ 5 - QS ++++++++++++++++++++++++++++++++++++++++++++++++++
    const qs = DSK_FW.QS.Ermitteln({
        actor: casterActor,
        gabenName,
        suchbegriffe: ["Seelenbindung Probe", "Seelenbindung"],
        testDataObj: typeof testData !== "undefined" ? testData : null,
        fallback: 0,
        protokollieren: true
    });

    if (qs <= 0) {
        await DSK_FW.GabenUI.AnfrageKarteErstellen({
            gabenName: vollerName,
            ahne,
            beschreibung: "Die Seele konnte nicht in den Schädel gebunden werden.",
            wirkender: casterName,
            ziele: [],
            misserfolge: [{ name: casterName }],
            dauerText: "Keine Wirkung",
            gmBereich: false,
            angewendet: true,
            erfolgreich: false,
            anfragenderUserId: game.user.id
        });

        await raeumeQSAuf(casterActor);
        return;
    }

    // +++ 6 - TARGETS PRÜFEN (1 GÜLTIGES BESIEGTES LEBEWESEN, REST = MISSERFOLG) +++
    const targets = Array.from(game.user.targets || []);

    if (!targets.length) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.warn(
            "Luna sagt 🌙: Bitte wähle zuerst die besiegte Beute per Target aus!"
        );
    }

    let gueltigesZielToken = null;
    const misserfolge = [];

    for (const tToken of targets) {
        const tActor = tToken?.actor;
        const tName = tToken?.name || tActor?.name || "Unbekanntes Ziel";

        if (gueltigesZielToken) {
            misserfolge.push({ name: tName });
            continue;
        }

        if (!tActor || !istSterblichesLebewesen(tActor)) {
            misserfolge.push({ name: tName });
            continue;
        }

        if (!istBesiegt(tActor, tToken)) {
            misserfolge.push({ name: tName });
            continue;
        }

        gueltigesZielToken = tToken;
    }

    if (!gueltigesZielToken) {
        await DSK_FW.GabenUI.AnfrageKarteErstellen({
            gabenName: vollerName,
            ahne,
            beschreibung: "Keines der ausgewählten Ziele ist ein besiegtes sterbliches Lebewesen.",
            wirkender: casterName,
            ziele: [],
            misserfolge,
            dauerText: "Keine Wirkung",
            gmBereich: false,
            angewendet: true,
            erfolgreich: false,
            anfragenderUserId: game.user.id
        });

        await raeumeQSAuf(casterActor);
        return;
    }

    const targetName = gueltigesZielToken.name || gueltigesZielToken.actor?.name || "Unbekanntes Ziel";
    const beschreibung = beschreibungFuer(casterName, targetName);

    // +++ 7 - GEMEINSAME KARTE ERSTELLEN ++++++++++++++++++++++++++
    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName,
        ahne,
        beschreibung,
        wirkender: casterName,
        ziele: [{ name: targetName, rolle: "Gebundene Seele" }],
        misserfolge,
        dauerText,
        gmBereich: false,
        angewendet: true,
        erfolgreich: true,
        anfragenderUserId: game.user.id
    });

    await raeumeQSAuf(casterActor);
}).call(this);
